// speaking_rate_calculator.js embebido
const LOG_PREFIX = '[speaking_rate]';
function log(msg) { console.log(`${LOG_PREFIX} ${msg}`); }

function countSpanishSyllables(text) {
  if (!text || typeof text !== 'string') return 0;
  let clean = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z\s']/g, ' ').replace(/\s+/g, ' ').trim();
  if (clean.length === 0) return 0;
  const words = clean.split(' ').filter(w => w.length > 0);
  let totalSyllables = 0;
  const strongVowels = new Set(['a','e','o']);
  const allVowels = new Set(['a','e','i','o','u']);
  for (const word of words) {
    let syllables = 0, i = 0;
    while (i < word.length) {
      if (!allVowels.has(word[i])) { i++; continue; }
      syllables++;
      const isStrong = strongVowels.has(word[i]);
      i++;
      while (i < word.length && allVowels.has(word[i])) {
        if (isStrong && strongVowels.has(word[i])) break;
        i++;
      }
    }
    totalSyllables += Math.max(syllables, 1);
  }
  return totalSyllables;
}

const NORMAL_RATE = 5.0, MIN_RATE = 0.75, MAX_RATE = 1.35, PAD = 0.15;
const data = $input.first().json;
const segments = data.segments.map((seg, idx) => {
  const targetDuration = Math.max(0.1, (seg.end - seg.start) - PAD * 2);
  const syls = countSpanishSyllables(seg.new_text || seg.text || '');
  if (syls === 0) return { ...seg, speaking_rate: 1.0, target_duration: targetDuration, estimated_syllables: 0, syllables_per_second: 0, warnings: [] };
  const reqSylsPerSec = syls / targetDuration;
  let rate = Math.max(MIN_RATE, Math.min(MAX_RATE, reqSylsPerSec / NORMAL_RATE));
  const warnings = [];
  if (reqSylsPerSec > 6.5) warnings.push('High density: ' + reqSylsPerSec.toFixed(1) + ' syl/s');
  return { ...seg, speaking_rate: Math.round(rate * 100) / 100, target_duration: targetDuration, estimated_syllables: syls, syllables_per_second: Math.round(reqSylsPerSec * 100) / 100, warnings };
});
return [{ json: { segments, video_path: data.video_path, video_duration: data.video_duration } }];

// circular_structure.js embebido - reordena en narrativa circular
const data = $input.first().json;
const { video_duration, segments, dubbed_video } = data;
const outputVideo = '/opt/ai_video_dubbing/output/final_circular.mp4';

function findHookSegment(segs, dur) {
  const min = dur * 0.75, max = dur * 0.90, mid = (min + max) / 2;
  let best = null, bestDist = Infinity;
  for (const s of segs) {
    const sm = (s.start + s.end) / 2;
    if (sm >= min && sm <= max) {
      const d = Math.abs(sm - mid);
      if (d < bestDist) { bestDist = d; best = s; }
    }
  }
  if (!best) {
    const t80 = dur * 0.80;
    for (const s of segs) { const d = Math.abs(s.start - t80); if (d < bestDist) { bestDist = d; best = s; } }
  }
  return best;
}

function fmt(sec) {
  const h = Math.floor(sec/3600), m = Math.floor((sec%3600)/60), s = (sec%60).toFixed(3);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${s.padStart(6,'0')}`;
}

const hook = findHookSegment(segments, video_duration);
const tmp = '/opt/ai_video_dubbing/temp/circular';
const esc = s => s.replace(/'/g, "'\\''");
const commands = [
  `mkdir -p '${tmp}'`,
  `ffmpeg -y -i '${esc(dubbed_video)}' -ss ${fmt(hook.start)} -t ${(hook.end-hook.start).toFixed(3)} -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k -avoid_negative_ts make_zero '${tmp}/p1_hook.mp4'`,
  `ffmpeg -y -f lavfi -i color=c=black:s=1920x1080:d=3:r=30 -f lavfi -i anullsrc=channel_layout=stereo:sample_rate=44100 -vf "drawtext=text='Pero todo empezo asi...':fontcolor=white:fontsize=72:font=Arial:x=(w-text_w)/2:y=(h-text_h)/2:alpha='if(lt(t,0.5),t/0.5,if(gt(t,2.5),(3-t)/0.5,1))'" -t 3 -c:v libx264 -preset fast -crf 18 -c:a aac -shortest '${tmp}/p2_trans.mp4'`,
  `ffmpeg -y -i '${esc(dubbed_video)}' -ss 00:00:00.000 -to ${fmt(hook.start)} -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k -avoid_negative_ts make_zero '${tmp}/p3_body.mp4'`,
  `ffmpeg -y -i '${esc(dubbed_video)}' -ss ${fmt(Math.max(0, video_duration-30))} -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k -avoid_negative_ts make_zero '${tmp}/p4_close.mp4'`,
  `printf "file '${tmp}/p1_hook.mp4'\nfile '${tmp}/p2_trans.mp4'\nfile '${tmp}/p3_body.mp4'\nfile '${tmp}/p4_close.mp4'" > '${tmp}/list.txt'`,
  `ffmpeg -y -f concat -safe 0 -i '${tmp}/list.txt' -c:v libx264 -preset fast -crf 18 -c:a aac -b:a 192k '${esc(outputVideo)}'`,
  `rm -rf '${tmp}'`
];

return [{ json: { ffmpeg_commands: commands, output_video: outputVideo, video_duration } }];

const data = $input.first().json;
return [{
  json: {
    success: true,
    message: 'Pipeline completado exitosamente',
    full_video: data.output_video,
    clips_directory: data.clips_dir,
    total_clips: data.clip_count,
    pipeline: [
      '1. Video descargado',
      '2. Transcrito con Whisper',
      '3. Traducido/reescrito a espanol',
      '4. Speaking rate calculado',
      '5. Audio generado con Edge TTS',
      '6. Audio sincronizado con video',
      '7. Estructura circular aplicada',
      '8. Cortado en clips para redes'
    ]
  }
}];

// Nodo de error global
const error = $input.first().json;
return [{
  json: {
    success: false,
    error: error.message || 'Error desconocido en el pipeline',
    node: error.node || 'unknown',
    timestamp: new Date().toISOString()
  }
}];
